-- 036 — Add 50 quantitative questions
--
-- Pure insert, no passage. Ids are deterministic:
-- md5(section || '|' || prompt)::UUID with ON CONFLICT DO NOTHING, so
-- re-running this file is a no-op. Nothing existing is deleted or updated,
-- and user_question_history is never touched.

WITH q(prompt, options, correct_index, difficulty, explanation) AS (VALUES
  ('Look at this series: 6, 13, 20, 27, 34, ... What number should come next?', '["40", "41", "42", "44"]'::JSONB, 1, 1, 'Check the gaps before anything else: 13 - 6 = 7 and 20 - 13 = 7, and that same 7 keeps showing up. A series that grows by a constant amount needs one more of that amount, so 34 + 7 = 41. The value 40 comes from adding 6 rather than 7, and 42 from adding 8, as if the gaps were growing.'),
  ('Look at this series: 90, 81, 72, 63, ... What number should come next?', '["52", "53", "54", "56"]'::JSONB, 2, 1, 'Each term drops by the same amount: 90 - 81 = 9 and 81 - 72 = 9, so the rule is subtract 9. That gives 63 - 9 = 54. The value 56 subtracts 7 and 53 subtracts 10, breaking the steady step. Every term here is a multiple of 9 counting down, and 54 = 9 × 6 fits right in.'),
  ('Look at this series: 2, 20, 200, 2000, ... What number should come next?', '["20000", "4000", "22000", "200000"]'::JSONB, 0, 1, 'Every term is 10 times the one before it, so each step adds one more zero. After 2000 comes 20000. The value 4000 comes from doubling, a rule that fits nothing earlier in the series. Multiplying by 10 never changes the leading digit, so any answer starting with something other than 2 cannot be right.'),
  ('Look at this series: 11, 15, 19, 23, 27, ... What number should come next?', '["29", "30", "33", "31"]'::JSONB, 3, 1, 'Look at the gaps: 15 - 11 = 4 and 19 - 15 = 4, so every step adds 4. The next term is 27 + 4 = 31. The value 29 adds only 2 and 33 adds 6, neither matching the steady step already set. Each term sits 3 above a multiple of 4, and 31 = 28 + 3 fits that too.'),
  ('Look at this series: 72, 66, 60, 54, ... What number should come next?', '["46", "47", "48", "50"]'::JSONB, 2, 1, 'The terms fall by a steady 6: 72 - 66 = 6 and 66 - 60 = 6. Continuing the rule, 54 - 6 = 48. The value 50 subtracts 4 and 46 subtracts 8, so both break the pattern. Every term is a multiple of 6 counting down - 72, 66, 60, 54, 48 - which confirms the answer.'),
  ('Look at this series: 7, 14, 28, 56, ... What number should come next?', '["63", "84", "118", "112"]'::JSONB, 3, 2, 'The gaps here grow instead of holding steady, which is a signal to try multiplying. Each term doubles: 7, 14, 28, 56, so the next is 56 × 2 = 112. The value 84 comes from adding 28, the gap before this one, but the gaps double as well, so the coming gap is 56 rather than 28.'),
  ('Look at this series: 4, 7, 6, 9, 8, 11, 10, ... What number should come next?', '["13", "9", "12", "14"]'::JSONB, 0, 2, 'Two rules take turns: add 3, then subtract 1. Follow it through - 4 + 3 = 7, 7 - 1 = 6, 6 + 3 = 9, 9 - 1 = 8, and onward. The move from 11 to 10 was the subtraction, so an addition comes next: 10 + 3 = 13. The value 9 applies the subtraction twice in a row, skipping a turn.'),
  ('Look at this series: 2, 4, 8, 14, 22, 32, ... What number should come next?', '["40", "44", "42", "46"]'::JSONB, 1, 2, 'When terms share no constant gap, study the gaps themselves: 2, 4, 6, 8, 10, each one 2 bigger than the one before. The next gap is 12, so 32 + 12 = 44. The value 42 repeats the gap of 10 without letting it grow, and 40 adds 8. Doubling would give 64, far too big for this pattern.'),
  ('Look at this series: 5, 10, 20, 35, 55, ... What number should come next?', '["70", "75", "80", "85"]'::JSONB, 2, 2, 'The gaps are 5, 10, 15, 20, growing by 5 every step, so the next gap is 25 and 55 + 25 = 80. The value 75 reuses the gap of 20 without growing it, and 70 reuses 15. Doubling looks tempting from 5, 10, 20, but 35 is not 40, so that rule falls apart at the fourth term.'),
  ('Look at this series: 3, 6, 18, 72, 360, ... What number should come next?', '["720", "1080", "1800", "2160"]'::JSONB, 3, 3, 'Divide each term by the one before to find the rule: 6 ÷ 3 = 2, 18 ÷ 6 = 3, 72 ÷ 18 = 4, 360 ÷ 72 = 5. The multipliers climb by one each time, so the next is 6: 360 × 6 = 2160. The value 720 keeps doubling, and 1800 multiplies by 5 again rather than moving the multiplier along.'),
  ('Look at this series: 2, 4, 10, 28, 82, ... What number should come next?', '["244", "164", "238", "246"]'::JSONB, 0, 3, 'The gaps are 2, 6, 18, 54, tripling each time, which points to a rule built on multiplying by 3. Test it: each term is 3 times the one before, minus 2. Check 28 × 3 - 2 = 82 ✓ So the next is 82 × 3 - 2 = 244. The value 246 triples 82 without subtracting the 2, and 164 only doubles.'),
  ('Look at this series: 5, 7, 11, 19, 35, ... What number should come next?', '["51", "67", "69", "70"]'::JSONB, 1, 3, 'The gaps are 2, 4, 8, 16, doubling every step, so the next gap is 32 and 35 + 32 = 67. The value 51 adds 16 again instead of doubling the gap. The value 70 doubles the term itself, but 5 does not double into 7, so that rule never worked. Here the gaps double, not the terms.'),
  ('Look at this series: 2, 9, 4, 18, 6, 27, 8, ... What number should come next?', '["10", "30", "36", "45"]'::JSONB, 2, 3, 'Two patterns are braided together. In the odd positions the terms run 2, 4, 6, 8, counting by 2; in the even positions they run 9, 18, 27, counting by 9. The blank falls in an even position, so it continues the nines: 27 + 9 = 36. The value 10 continues the other strand, the one that gave 8.'),
  ('Examine the figures described and find the best answer. Figure A is a rectangle 7 by 4. Figure B is a square with side 5.', '["Figure A has the greater area and the greater perimeter.", "Figure B has the greater area.", "The perimeters are equal.", "Figure B has the greater perimeter, but A has the greater area."]'::JSONB, 0, 1, 'Compare area and perimeter separately, since a bigger area need not bring a bigger perimeter. Rectangle: area 7 × 4 = 28, perimeter 2(7 + 4) = 22. Square: area 5 × 5 = 25, perimeter 20. The rectangle wins both, so claiming the perimeters are equal, or that Figure B has the greater area, does not hold.'),
  ('Examine the figures described and find the best answer. Figure A is a square with side 10. Figure B is a rectangle 20 by 5.', '["Figure A has the greater area and the greater perimeter.", "The areas and the perimeters are equal.", "The areas are equal, but B has the greater perimeter.", "Figure B has the greater area."]'::JSONB, 2, 1, 'Same area, different shape. Both cover 100 square units, 10 × 10 and 20 × 5, so neither figure holds more inside. Around the outside, the square needs 40 while the long rectangle needs 2(20 + 5) = 50. Stretching a shape thinner keeps the area but costs more fencing, so B has the greater perimeter.'),
  ('Examine the figures described and find the best answer. Figure A is a triangle with base 8 and height 5. Figure B is a rectangle 4 by 6.', '["The areas are equal.", "Figure B has the greater area.", "Figure A has the greater area.", "The area of A is twice the area of B."]'::JSONB, 1, 1, 'A triangle''s area is half its base times its height, so its larger-looking measurements can still lose. Figure A gives (1/2) × 8 × 5 = 20 while the rectangle gives 4 × 6 = 24, so Figure B has the greater area. Twice the area of A would be 40, nowhere near 24, so that comparison fails as well.'),
  ('Examine the figures described and find the best answer. Figure A is a rectangle 6 by 2. Figure B is a triangle with base 6 and height 4.', '["Figure A has the greater area.", "Figure B has the greater area.", "The area of B is twice the area of A.", "The areas are equal."]'::JSONB, 3, 1, 'A triangle covers exactly half of the rectangle built on the same base and height, which is why the formula halves. Rectangle: 6 × 2 = 12. Triangle: (1/2) × 6 × 4 = 12. They tie. Leaving out the 1/2 would give the triangle 24 and make it look like twice the area of the rectangle, but that doubles a figure that only ties.'),
  ('Examine the figures described and find the best answer. Figure A is a right triangle with legs 6 and 8. Figure B is a rectangle 5 by 7.', '["Figure A has the greater perimeter and the greater area.", "Figure B has the greater perimeter.", "The perimeters are equal, but B has the greater area.", "The areas are equal."]'::JSONB, 2, 2, 'Legs of 6 and 8 make a 6-8-10 right triangle, so its perimeter is 6 + 8 + 10 = 24 and its area is (1/2)(6)(8) = 24. The rectangle''s perimeter is 2(5 + 7) = 24 as well, and its area is 5 × 7 = 35. So the perimeters are equal but B has the greater area, which rules out equal areas.'),
  ('Examine the figures described and find the best answer. Figure A is a circle with radius 10. Figure B is a rectangle 20 by 15. Use pi = 3.14.', '["Figure A has the greater area.", "Figure B has the greater area.", "The areas are equal.", "The area of B is twice the area of A."]'::JSONB, 0, 2, 'Work both areas out rather than trusting how the shapes look. Circle: 3.14 × 10 × 10 = 314. Rectangle: 20 × 15 = 300. Figure A has the greater area, though by only about 5%, which is why guessing that the areas are equal feels reasonable. The rectangle would need to be 20 by 15.7 to catch up.'),
  ('Examine the figures described and find the best answer. Figure A is a rectangular box 3 by 3 by 6. Figure B is a cube with edge 4.', '["Figure A has the greater volume and the greater surface area.", "The volumes are equal.", "Figure A has the greater surface area.", "Figure B has the greater volume and the greater surface area."]'::JSONB, 3, 2, 'Check volume and surface area one at a time. Volumes: 3 × 3 × 6 = 54 against 4 × 4 × 4 = 64. Surface areas: the box has 2(9 + 18 + 18) = 90 and the cube has 6 × 16 = 96. The cube is bigger on both counts, so any claim that Figure A leads in volume or surface area fails.'),
  ('Examine the figures described and find the best answer. A rectangle 12 by 8 has a rectangle 4 by 3 cut away from one corner; the part that remains is shaded. Figure B is a square with side 9.', '["Figure B is greater than the shaded part of A.", "The shaded part of A is greater than B.", "The shaded part of A equals B.", "The shaded part of A is twice B."]'::JSONB, 1, 3, 'Subtract the cut-away piece before comparing. The whole rectangle is 12 × 8 = 96 and the removed corner is 4 × 3 = 12, so the shaded part is 96 - 12 = 84. Square B is 9 × 9 = 81. The shaded part is greater, but by only 3, so calling them equal comes close without being right.'),
  ('Examine the figures described and find the best answer. Figure A is a triangle with sides 13, 13 and 10, with a height of 12 drawn to the side of length 10. Figure B is a rectangle 6 by 12.', '["The perimeters are equal, but B has the greater area.", "Figure A has the greater perimeter.", "The perimeters are equal, but A has the greater area.", "The areas are equal."]'::JSONB, 0, 3, 'Equal perimeters can hide very different areas. Triangle: 13 + 13 + 10 = 36 around the outside, and (1/2)(10)(12) = 60 inside. Rectangle: 2(6 + 12) = 36 around, and 6 × 12 = 72 inside. The perimeters match, but B holds more area, so the claim that A has the greater area does not stand.'),
  ('Examine the figures described and find the best answer. Figure A is a square whose area is 64. Figure B is a square whose perimeter is 40.', '["Figure A has the greater perimeter and the greater area.", "The areas are equal.", "Figure B has the greater area and the greater perimeter.", "The area of B is twice the area of A."]'::JSONB, 2, 3, 'Convert both figures to side lengths and the rest follows. A has area 64, so its side is 8 and its perimeter is 4 × 8 = 32. B has perimeter 40, so its side is 40 ÷ 4 = 10 and its area is 100. B leads both ways. And 100 is not twice 64, so that comparison fails too.'),
  ('Examine the figures described and find the best answer. Figure A is a trapezoid with parallel sides 5 and 11 and height 6. Figure B is a triangle with base 12 and height 8.', '["Figure A has the greater area.", "The areas are equal.", "Figure B has the greater area.", "The area of B is twice the area of A."]'::JSONB, 1, 3, 'A trapezoid''s area is the average of the parallel sides times the height: (5 + 11)/2 = 8, and 8 × 6 = 48. The triangle gives (1/2)(12)(8) = 48, so the areas are equal. Adding both parallel sides without averaging would hand the trapezoid 96 and make it look twice the triangle, which is the usual slip.'),
  ('Examine the figures described and find the best answer. A square with side 12 has a circle of diameter 12 removed from it; the four corner pieces that remain are shaded. Use pi = 3.14.', '["The shaded area is between 20 and 25.", "The shaded area is between 35 and 40.", "The shaded area is more than half the square.", "The shaded area is between 30 and 32."]'::JSONB, 3, 3, 'The four corner pieces are whatever the circle leaves behind. The square is 12 × 12 = 144, and a diameter of 12 means a radius of 6, so the circle covers 3.14 × 36 = 113.04. Shaded = 144 - 113.04 = 30.96, which lands between 30 and 32. The circle takes nearly 79%, so the corners are far under half.'),
  ('Examine (a), (b), and (c) and find the best answer. (a) 3 × 4   (b) 2 × 7   (c) 24 divided by 2', '["(b) is the greatest, and (a) equals (c).", "(a), (b), and (c) are all equal.", "(a) is the greatest, and (b) equals (c).", "(c) is less than (a), and (b) is the smallest."]'::JSONB, 0, 1, 'Work all three out before comparing. (a) 3 × 4 = 12, (b) 2 × 7 = 14, (c) 24 ÷ 2 = 12. So (b) is the greatest and (a) ties with (c). Saying (a) is the greatest reverses the real order, and (c) is not less than (a) - those two are exactly the same size.'),
  ('Examine (a), (b), and (c) and find the best answer. (a) 1/3   (b) 0.3   (c) 30%', '["All three are equal.", "(b) is greater than (a), and (c) is the smallest.", "(a) is the greatest, and (b) equals (c).", "(c) is the greatest."]'::JSONB, 2, 1, 'Put all three into decimal form. Here 0.3 and 30% are two spellings of one number, 0.30, but 1/3 = 0.3333..., with threes that never stop, so it edges past both. That makes (a) the greatest while (b) equals (c). Saying all three are equal is the common trap: 1/3 is a bit more than 0.3.'),
  ('Examine (a), (b), and (c) and find the best answer. (a) 10 - 4   (b) 10 divided by 2   (c) 3 × 2', '["All three are equal.", "(a) equals (c), and both are greater than (b).", "(a) equals (b), and both are greater than (c).", "(a) is greater than (c)."]'::JSONB, 1, 1, 'Compute each one: 10 - 4 = 6, 10 ÷ 2 = 5, and 3 × 2 = 6. So (a) and (c) both give 6, and both beat (b). Saying (a) equals (b) picks the wrong pair for the tie - the division is the odd one out here, while the subtraction and the multiplication match.'),
  ('Examine (a), (b), and (c) and find the best answer. (a) 5% of 200   (b) 10% of 100   (c) 20% of 60', '["All three are equal.", "(a) is greater than (b).", "(b) is greater than (c).", "(c) is the greatest."]'::JSONB, 3, 1, 'A percent of a number means multiply. (a) 5% of 200 = 10, (b) 10% of 100 = 10, (c) 20% of 60 = 12. So (c) is the greatest while (a) and (b) tie. Saying (a) is greater than (b) misses that tie, and the three are not all equal because 12 stands apart from the two tens.'),
  ('Examine (a), (b), and (c) and find the best answer. (a) 2/5   (b) 0.45   (c) 3/8', '["(b) is greater than (a), and (a) is greater than (c).", "(a) is the greatest.", "(c) is greater than (a), and (a) is greater than (b).", "(a) equals (b)."]'::JSONB, 0, 2, 'Turn the fractions into decimals so all three sit on one scale: 2/5 = 0.400, (b) is already 0.450, and 3/8 = 0.375. In order, (b) is greater than (a), and (a) is greater than (c). Choosing (a) as the greatest is easy if you assume a fraction beats a decimal, but 0.45 is larger than 0.40.'),
  ('Examine (a), (b), and (c) and find the best answer. (a) the average of 6 and 14   (b) the average of 8, 10, and 12   (c) the average of 2, 8, 10, and 16', '["All three are equal.", "(c) is the smallest, and (a) equals (b).", "(a) is greater than (b), and (c) is the smallest.", "(c) is the greatest."]'::JSONB, 1, 2, 'An average is the total divided by how many numbers there are. (a) 20 ÷ 2 = 10, (b) 30 ÷ 3 = 10, (c) 36 ÷ 4 = 9. So (c) is the smallest and (a) equals (b). Having four numbers does not make (c) the greatest, since the count sits in the denominator. The three results are not all equal either, because 9 falls below the two tens.'),
  ('Examine (a), (b), and (c) and find the best answer. (a) 2/3 of 1/2   (b) 1/2 of 2/3   (c) 3/4 of 1/2', '["All three are equal.", "(a) is the greatest.", "(a) equals (c), and (b) is greater than both.", "(a) equals (b), and (c) is greater than both."]'::JSONB, 3, 2, 'Multiplication does not care about order, so 2/3 of 1/2 and 1/2 of 2/3 are the same thing: both equal 1/3. Then (c) is 3/4 × 1/2 = 3/8. Compare 1/3 and 3/8 over a common bottom of 24: 8/24 against 9/24, so (c) is the larger. That is why calling all three equal does not work.'),
  ('Examine (a), (b), and (c) and find the best answer. (a) 1/2 + 1/4 + 1/8   (b) 1 - 1/8   (c) 0.9', '["(c) is the greatest, and (a) equals (b).", "All three are equal.", "(a) is greater than (c), and (b) equals (c).", "(b) is the greatest."]'::JSONB, 0, 3, 'Add and subtract in eighths. (a) 1/2 + 1/4 + 1/8 = 4/8 + 2/8 + 1/8 = 7/8, and (b) 1 - 1/8 = 7/8 as well, so those two tie at 0.875. Then (c) 0.9 is larger, so the three values are not all equal. Calling (b) the greatest overlooks that 0.9 beats 0.875, a small gap but a real one.'),
  ('Examine (a), (b), and (c) and find the best answer. (a) 3/7   (b) 5/11   (c) 4/9', '["(a) is the greatest and (c) is the smallest.", "(c) is greater than (b).", "(b) is the greatest and (a) is the smallest.", "(a) equals (c)."]'::JSONB, 2, 3, 'Compare fractions two at a time by cross-multiplying. For 3/7 against 4/9: 3 × 9 = 27 versus 4 × 7 = 28, so 4/9 is bigger. For 4/9 against 5/11: 44 versus 45, so 5/11 is bigger. The order runs (b), then (c), then (a), which makes (a) the smallest rather than the greatest.'),
  ('Examine (a), (b), and (c) and find the best answer. (a) 25% of 64   (b) 64 decreased by 75%   (c) 64 divided by 4', '["(b) is smaller than (a), and (a) equals (c).", "(a), (b), and (c) are all equal.", "(a) is greater than (c).", "(c) is the greatest."]'::JSONB, 1, 3, 'Three operations that sound different do the same job here. 25% of 64 is 16. Decreasing 64 by 75% leaves the other 25%, again 16. And 64 ÷ 4 is 16, since a quarter is 25%. All three are equal, so (b) is not smaller than (a). Reading a 75% decrease as though it lands below the others is what makes the tie easy to miss.'),
  ('Examine (a), (b), and (c) and find the best answer. (a) the number of 1/4s in 5   (b) 5 + 4   (c) 5 divided by 1/4', '["All three are equal.", "(a) equals (b), and both are greater than (c).", "(c) is the smallest.", "(a) equals (c), and both are greater than (b)."]'::JSONB, 3, 3, 'Asking how many 1/4s fit inside 5 is exactly what dividing 5 by 1/4 means, so (a) and (c) are the same question, and both give 20. Meanwhile (b) is 5 + 4 = 9. Dividing by an amount under 1 makes the result grow, which is why 20 beats 9 rather than the other way around.'),
  ('Examine (a), (b), and (c) and find the best answer. (a) 3 cubed minus 2 cubed   (b) 2 × 3 squared   (c) 4 squared plus 3', '["All three are equal.", "(b) is the greatest.", "(b) is the smallest, and (a) equals (c).", "(a) is greater than (c), and (b) is the smallest."]'::JSONB, 2, 3, 'Handle each power carefully. (a) 3 cubed is 27 and 2 cubed is 8, so 27 - 8 = 19. (b) 2 × 3 squared means 2 × 9 = 18, not 6² = 36. (c) 4 squared plus 3 is 16 + 3 = 19. So (b) is the smallest and (a) equals (c). The top spot is a tie, so (b) is not the greatest, and the three results are not all equal.'),
  ('What number is 5 more than 1/4 of 40?', '["15", "10", "14", "20"]'::JSONB, 0, 1, 'Read the sentence in pieces, innermost part first. One fourth of 40 is 10, and 5 more than 10 is 15. The value 10 stops at the fraction and never adds the 5, and 20 comes from taking half of 40 rather than a quarter. Check by working backwards: 15 - 5 = 10, which is 40 ÷ 4 ✓'),
  ('What number is 3 less than half of 22?', '["7", "11", "8", "14"]'::JSONB, 2, 1, 'Take the half first, then do the subtraction the words describe. Half of 22 is 11, and 3 less than 11 is 8. The value 11 stops at the halving step, and 14 is 11 + 3, adding where the sentence says less. Check by reversing it: 8 + 3 = 11, and 11 doubled is 22 ✓'),
  ('What number is twice the sum of 7 and 8?', '["15", "30", "22", "56"]'::JSONB, 1, 1, 'The wording says to add first and double after: 7 + 8 = 15, then 2 × 15 = 30. The value 15 gives the sum without doubling, and 56 comes from multiplying 7 × 8 rather than adding them. Check by halving the answer: 30 split in two is 15, the sum you started from ✓'),
  ('One third of what number is 15?', '["5", "18", "48", "45"]'::JSONB, 3, 1, 'When a fraction of a number is given, work backwards by multiplying. If one third is 15, the whole is three of those thirds: 3 × 15 = 45. The value 5 takes a third of 15 instead, heading the wrong direction, since a whole number has to be bigger than one third of itself, not smaller.'),
  ('What number is 10% of 1/2 of 400?', '["4", "20", "40", "200"]'::JSONB, 1, 2, 'Work from the inside out. Half of 400 is 200, and 10% of 200 means dividing by 10, giving 20. The value 40 takes 10% of 400 without halving first, and 200 stops after the halving step. Sanity check: 20 is one twentieth of 400, which is what a half and then a tenth should produce ✓'),
  ('What number is 7 more than the product of 4 and 6?', '["17", "28", "34", "31"]'::JSONB, 3, 2, 'Product means the result of multiplying, so handle that part first: 4 × 6 = 24, then 24 + 7 = 31. The value 17 subtracts 7 where the sentence says more, and 28 comes from multiplying 4 by 7 and leaving the 6 out of the problem. Check by undoing it: 31 - 7 = 24, which is 4 × 6 ✓'),
  ('60% of what number is 3 times 9?', '["45", "16", "27", "54"]'::JSONB, 0, 2, 'Finish the right side first: 3 times 9 is 27. Now 0.6 of the number is 27, so the number is 27 ÷ 0.6 = 45. Because 60% of a number is less than the number itself, the answer has to be larger than 27, which rules out 16 immediately. The value 27 is the part, not the whole.'),
  ('What number is 4 less than 3/4 of the difference between 100 and 20?', '["60", "71", "56", "76"]'::JSONB, 2, 3, 'Peel the sentence apart from the inside. The difference between 100 and 20 is 80. Three fourths of 80 is 60. Then 4 less than 60 gives 56. The value 60 stops one step early, and 76 subtracts 4 from 80 without ever taking three fourths. Check: 56 + 4 = 60, which is 3/4 of 80 ✓'),
  ('Two thirds of what number is 5 more than 1/2 of 30?', '["20", "25", "45", "30"]'::JSONB, 3, 3, 'Build the right side first: half of 30 is 15, and 5 more makes 20. Now two thirds of the number is 20, so the number is 20 × 3/2 = 30. The value 20 is the two-thirds part itself rather than the whole, and 45 multiplies by 3 while skipping the divide by 2. Check: 2/3 of 30 = 20 ✓'),
  ('What number is 1/6 of the sum of 4 squared and 2 cubed?', '["3", "4", "5", "6"]'::JSONB, 1, 3, 'Sort out the powers before dividing. 4 squared is 4 × 4 = 16 and 2 cubed is 2 × 2 × 2 = 8, so the sum is 24. One sixth of 24 is 4. The value 6 comes from dividing 24 by 4 instead of by 6, mixing up the two numbers. Check by multiplying back: 6 × 4 = 24 ✓'),
  ('What number is 12 more than 40% of 150?', '["54", "60", "72", "78"]'::JSONB, 2, 3, 'Find the percent first, then add. 10% of 150 is 15, so 40% is 4 × 15 = 60, and 60 + 12 = 72. The value 60 stops before the 12 is added, which is the easiest slip to make here. Check by undoing that final step: 72 - 12 = 60, and 60 is indeed 40% of 150 ✓'),
  ('Three times a number, decreased by 8, equals half of 44. What is the number?', '["10", "6", "12", "14"]'::JSONB, 0, 3, 'Translate the sentence one piece at a time: half of 44 is 22, so three times the number, minus 8, equals 22. Add the 8 back to get 30, then divide by 3 to get 10. Test 12 and you get 3 × 12 - 8 = 28, which is not 22, so it fails. Check: 3 × 10 - 8 = 22 ✓'),
  ('What number is 1/3 of 1/4 of 20% of 300?', '["4", "5", "15", "20"]'::JSONB, 1, 3, 'Chain the operations from the inside out. 20% of 300 is 60; one fourth of 60 is 15; one third of 15 is 5. The value 15 stops one step early, and 20 comes from taking a third of 60 while skipping the quarter. Shortcut check: 1/3 × 1/4 × 1/5 = 1/60, and 300 ÷ 60 = 5 ✓')
)
INSERT INTO questions (id, section, passage, prompt, options, correct_index, difficulty, explanation)
SELECT md5('quantitative' || '|' || q.prompt)::UUID, 'quantitative'::section_type, NULL,
       q.prompt, q.options, q.correct_index, q.difficulty, q.explanation
FROM q
ON CONFLICT (id) DO NOTHING;

-- ── Verification: expect 50 rows ─────────────────────────────────────
SELECT '036 quantitative' AS migration, COUNT(*)::TEXT AS present, '50' AS expected
FROM questions
WHERE id IN (
  md5('quantitative' || '|' || 'Look at this series: 6, 13, 20, 27, 34, ... What number should come next?')::UUID,
  md5('quantitative' || '|' || 'Look at this series: 90, 81, 72, 63, ... What number should come next?')::UUID,
  md5('quantitative' || '|' || 'Look at this series: 2, 20, 200, 2000, ... What number should come next?')::UUID,
  md5('quantitative' || '|' || 'Look at this series: 11, 15, 19, 23, 27, ... What number should come next?')::UUID,
  md5('quantitative' || '|' || 'Look at this series: 72, 66, 60, 54, ... What number should come next?')::UUID,
  md5('quantitative' || '|' || 'Look at this series: 7, 14, 28, 56, ... What number should come next?')::UUID,
  md5('quantitative' || '|' || 'Look at this series: 4, 7, 6, 9, 8, 11, 10, ... What number should come next?')::UUID,
  md5('quantitative' || '|' || 'Look at this series: 2, 4, 8, 14, 22, 32, ... What number should come next?')::UUID,
